#pragma once
#include "recovery_b1038_cases.hpp"
#include <fstream>
#include <vector>
#include <array>
#include <algorithm>
#include <cstring>
#include <stdexcept>
namespace ra2::platform::shortcut1038 {
namespace b=ra2::recovered::b1038;
inline void need(bool ok,const char*s){if(!ok)throw std::runtime_error(s);}
struct Mark{unsigned off,kind,id,offset;};
struct Block{unsigned ordinal;std::vector<unsigned char>bytes;std::vector<Mark>marks;};
struct Phase{std::vector<unsigned>sizes;std::vector<std::array<unsigned,3>>events;std::vector<Block>snapshots,live;std::vector<std::pair<unsigned,unsigned>>arena_bytes;std::vector<Mark>arena_marks;};
struct Profile{unsigned root,fixture_allocations,object,vector;std::array<Phase,4>phase;};
inline unsigned word(std::istream&f){unsigned n=0;f.read(reinterpret_cast<char*>(&n),4);need(bool(f),"1038 full symbolic oracle word");return n;}
inline std::vector<Mark>marks(std::istream&f){const auto count=word(f);need(count<1024u,"1038 bounded oracle marks");std::vector<Mark>v;for(unsigned n=0;n<count;++n)v.push_back({word(f),word(f),word(f),word(f)});return v;}
inline std::vector<Block>blocks(std::istream&f){const auto count=word(f);need(count<128u,"1038 bounded oracle blocks");std::vector<Block>v;for(unsigned n=0;n<count;++n){Block b{};b.ordinal=word(f);const auto size=word(f);need(size>0u&&size<=4096u,"1038 oracle payload bounds");b.bytes.resize(size);f.read(reinterpret_cast<char*>(b.bytes.data()),size);need(bool(f),"1038 complete oracle payload");b.marks=marks(f);v.push_back(std::move(b));}return v;}
inline Profile load(unsigned selected){std::ifstream f("analysis/block1038/golden.bin",std::ios::binary);need(bool(f),"1038 frozen independent symbolic oracle input");char magic[4]{};f.read(magic,4);need(std::memcmp(magic,"SC38",4)==0&&word(f)==4u,"1038 oracle identity/version/count");Profile result{};unsigned hits=0u;for(unsigned n=0;n<4u;++n){Profile p{};p.root=word(f);p.fixture_allocations=word(f);p.object=word(f);p.vector=word(f);for(auto&q:p.phase){const auto count=word(f);need(count<=64u,"1038 bounded golden allocations");for(unsigned n=0;n<count;++n)q.sizes.push_back(word(f));const auto ne=word(f);need(ne<=256u,"1038 bounded golden event stream");for(unsigned n=0;n<ne;++n)q.events.push_back({word(f),word(f),word(f)});q.snapshots=blocks(f);q.live=blocks(f);const auto nb=word(f);need(nb<1024u,"1038 arena oracle bounded stores");for(unsigned n=0;n<nb;++n){const auto off=word(f),value=word(f);need(off<65536u&&value<256u,"1038 arena byte store");q.arena_bytes.push_back({off,value});}q.arena_marks=marks(f);}if(p.root==selected){result=std::move(p);++hits;}}need(hits==1u&&f.peek()==std::char_traits<char>::eof(),"1038 selected exact oracle and EOF");return result;}
inline void put(std::vector<unsigned char>&v,unsigned off,unsigned value){need(off+4u<=v.size(),"1038 full word materialization bounds");for(unsigned k=0;k<4u;++k)v[off+k]=static_cast<unsigned char>(value>>(k*8u));}
inline void apply(std::vector<unsigned char>&v,const std::vector<Mark>&marks,const b::Case&c,const std::vector<unsigned>&a,unsigned base){for(const auto&m:marks){need(m.off<v.size(),"1038 typed oracle store range");if(m.kind==1u){need(m.id<a.size(),"1038 exact heap pointer ordinal");put(v,m.off,a[m.id]+m.offset);}else if(m.kind==2u)put(v,m.off,base+m.id);else if(m.kind==3u)v[m.off]=static_cast<unsigned char>(c.letter);else if(m.kind==4u)v[m.off]=static_cast<unsigned char>(c.letter+32);else if(m.kind==5u)put(v,m.off,0x700u|unsigned(c.letter));else need(false,"1038 exact typed oracle mark");}}
inline std::vector<unsigned char>payload(const Block&v,const b::Case&c,const b::HeapAdapter&h,unsigned base){auto out=v.bytes;apply(out,v.marks,c,h.addresses,base);return out;}
inline std::vector<unsigned char>arena(const Phase&q,const b::Case&c,const b::HeapAdapter&h,unsigned base){std::vector<unsigned char>v(65536u);for(unsigned k=0;k<v.size();++k)v[k]=static_cast<unsigned char>(c.seed+k*131u+(k>>3u));for(const auto&x:q.arena_bytes)v[x.first]=static_cast<unsigned char>(x.second);apply(v,q.arena_marks,c,h.addresses,base);return v;}
inline void verify(const Profile&p,unsigned phase,const b::Case&c,b::HeapAdapter&h,const unsigned char*data,unsigned base,unsigned lock9){const auto&q=p.phase.at(phase);need(h.addresses.size()==q.sizes.size()&&h.allocation_flags.size()==q.sizes.size()&&h.events().size()==q.events.size()&&h.snapshots.size()==q.snapshots.size()&&h.live().size()==q.live.size(),"1038 independent exact phase lifetime counts");for(unsigned k=0;k<q.events.size();++k){const auto&e=h.events()[k];const auto&x=q.events[k];need(unsigned(e.kind)==x[0]&&e.ordinal==x[1]&&e.size==x[2],"1038 independent ordered heap/CS9 event stream");if(e.kind==b::Event::Kind::allocate)need(e.ordinal<q.sizes.size()&&e.size==q.sizes[e.ordinal]&&e.address==h.addresses[e.ordinal]&&e.result==e.address&&h.allocation_flags[e.ordinal]==0u,"1038 real malloc ordinal/request/full pointer/flags0");if(e.kind==b::Event::Kind::release)need(e.address==h.addresses[e.ordinal]&&e.result!=0u,"1038 real full HeapFree BOOL success");if(e.kind==b::Event::Kind::enter_lock||e.kind==b::Event::Kind::leave_lock)need(e.address==lock9,"1038 genuine original criticalsection9 identity");}for(unsigned k=0;k<q.snapshots.size();++k){const auto&g=q.snapshots[k];const auto&s=h.snapshots[k];need(s.ordinal==g.ordinal,"1038 independently expected free snapshot ordinal");const auto expected=payload(g,c,h,base);if(s.bytes!=expected){unsigned j=0;while(j<s.bytes.size()&&s.bytes[j]==expected[j])++j;std::fprintf(stderr,"1038 phase%u snapshot%u ordinal%u byte%u actual%02x expected%02x\n",phase,k,s.ordinal,j,j<s.bytes.size()?s.bytes[j]:0u,j<expected.size()?expected[j]:0u);need(false,"1038 complete transient pre-free payload");}}for(const auto&g:q.live){need(g.ordinal<h.addresses.size(),"1038 exact live expected ordinal");const auto expected=payload(g,c,h,base);auto id=h.identify(h.addresses[g.ordinal],unsigned(expected.size()));need(id.ordinal==g.ordinal&&id.offset==0u,"1038 complete live allocation identity");for(unsigned k=0;k<expected.size();++k)need(h.r8(h.addresses[g.ordinal]+k)==expected[k],"1038 full retained object/vector/graph payload");}const auto expected=arena(q,c,h,base);need(std::equal(expected.begin(),expected.end(),data),"1038 independent whole arena/holder/parser/receiver state");}
inline std::vector<unsigned char>normalized_arena(const Profile&p,const b::Case&c,const b::HeapAdapter&h,unsigned base,const unsigned char*data){const auto expected=arena(p.phase[1],c,h,base);need(std::equal(expected.begin(),expected.end(),data),"1038 full arena proven before explicit owner normalization");auto out=expected;for(const auto&m:p.phase[1].arena_marks)if(m.kind==1u){const auto id=h.identify(h.addresses[m.id]+m.offset);need(id.ordinal==m.id&&id.offset==m.offset,"1038 explicit exact live owner pointer relation");put(out,m.off,0xf1000000u+m.id*0x1000u+m.offset);}return out;}
inline void compare_events(const b::HeapAdapter&a,const b::HeapAdapter&d){need(a.events().size()==d.events().size(),"1038 paired full heap events");for(unsigned k=0;k<a.events().size();++k){const auto&x=a.events()[k],&y=d.events()[k];need(x.kind==y.kind&&x.ordinal==y.ordinal&&x.size==y.size,"1038 paired heap ordinal and lifetime");if(x.kind==b::Event::Kind::release)need(x.result==y.result,"1038 exact full original/model HeapFree BOOL");if(x.kind==b::Event::Kind::enter_lock||x.kind==b::Event::Kind::leave_lock)need(x.address==y.address,"1038 same real original CS9");}}
}
